import{boot,e,field,editAttrs}from'../creative-kit/ui.js?v=0.6.0';import{make,validate,apply,markdown,METHODS,CONCERN_FIELDS,DESIGN_FIELDS}from'./state.js?v=0.6.0';
const prompts={need:'Could the concern disappear because this requirement is no longer needed?',delivery:'Could the benefit arrive through a different channel, moment or actor?',exposure:'Could a smaller scope, limit or reversible trial contain the concern?'};
function render(w){return `<section class="benefit-banner">${field('original-benefit','Keep the original benefit visible',w.benefit,editAttrs('workspace','','benefit'),'What made this concept promising before the objections arrived?')}</section><div class="objection-layout"><aside class="concern-bank"><div class="section-head"><div><h2>The concern beneath the objection</h2><p>Drag a concern onto a design route, or use Fork. The benefit should survive the response.</p></div></div>${w.concerns.map(c=>`<article class="card concern" data-drag-id="${e(c.id)}"><div class="card-top"><span>Objection</span><button class="drag-handle" data-drag-handle data-action="fork-menu" data-id="${e(c.id)}" aria-label="Fork from ${e(c.objection)}">⠿</button></div><h3>${e(c.objection||'State the objection')}</h3><p><strong>Underneath:</strong> ${e(c.concern||'What risk or need is this protecting?')}</p><div class="card-actions"><button class="text-button" data-action="edit-concern" data-id="${e(c.id)}">Clarify</button><button class="text-button" data-action="fork-menu" data-id="${e(c.id)}">Fork alternatives ↗</button></div></article>`).join('')}<button data-action="add-concern">+ Objection</button></aside><section class="design-routes">${Object.entries(METHODS).map(([key,name])=>`<section class="route" data-drop-id="method:${key}"><header><span class="route-symbol">${{need:'−',delivery:'⇄',exposure:'◌'}[key]}</span><div><h2>${name}</h2><p>${prompts[key]}</p></div></header><div class="design-list">${w.designs.filter(d=>d.method===key).map(d=>`<article class="card design ${w.selected===d.id?'chosen':''}" data-drop-id="design:${e(d.id)}"><div class="card-top"><span>Addresses ${d.concerns.length} concern${d.concerns.length>1?'s':''}</span>${w.selected===d.id?'<span class="tag">To test</span>':''}</div><h3>${e(d.title)}</h3><p>${e(d.mechanism||'Explain a different way to retain the benefit.')}</p><div class="preserved"><span>BENEFIT RETAINED</span><p>${e(d.benefit||'How does the original benefit survive?')}</p></div>${d.stale?'<p class="tag amber">Concern or benefit changed · recheck</p>':''}<p class="concern-links">${d.concerns.map(id=>'↳ '+e(w.concerns.find(c=>c.id===id).objection)).join('<br>')}</p><div class="card-actions"><button data-action="develop" data-id="${e(d.id)}">Develop</button><button class="text-button" data-action="select" data-id="${e(d.id)}">Choose a test</button></div></article>`).join('')||'<div class="empty">Drop a concern to create a branch here.</div>'}</div></section>`).join('')}</section></div>`;}
function editConcern(id,k){const c=k.w().concerns.find(c=>c.id===id);k.open(CONCERN_FIELDS.map((f,i)=>field(`concern-${f}`,['The objection','The concern beneath it','What observation would support or challenge it?'][i],c[f],editAttrs('concerns',id,f))).join('')+`<div class="toolbar"><button class="primary" data-action="close">Done</button><button class="delete" data-action="remove-concern" data-id="${e(id)}" ${k.w().designs.some(d=>d.concerns.includes(id))?'disabled':''}>Remove unused concern</button></div>`,'Clarify the objection');}
function develop(id,k){const d=k.w().designs.find(d=>d.id===id);k.open(`<p>${prompts[d.method]}</p><p class="hint">Original benefit: ${e(k.w().benefit)}</p>`+DESIGN_FIELDS.map((f,i)=>field(`design-${f}`,['Alternative name','How does it work?','How does the original benefit survive?','What cost or unresolved concern remains?','Smallest useful test'][i],d[f],editAttrs('designs',id,f))).join('')+`<div class="toolbar"><button class="primary" data-action="review" data-id="${e(id)}">Benefit and concern checked</button><button data-action="close">Done</button><button class="delete" data-action="remove-design" data-id="${e(id)}">Remove design</button></div>`,'Develop the alternative');}
function fork(k,concern,method){const id=k.uid();if(k.act({type:'fork',id,concern,method}))develop(id,k);}
boot({route:'objections',code:'S07',title:'Objections into alternatives',description:'Keep what was promising. Use the concern to create a different design.',make,validate,apply,markdown,render,drop:(concern,to,k)=>{const [type,id]=to.split(':');if(type==='method')fork(k,concern,id);else k.act({type:'link',id,concern});},handle:(a,d,k)=>{if(a==='edit-concern')editConcern(d.id,k);else if(a==='add-concern'){const id=k.uid();if(k.act({type:a,id}))editConcern(id,k);}else if(a==='develop')develop(d.id,k);else if(a==='fork-menu')k.open('<div class="dialog-options">'+Object.entries(METHODS).map(([key,name])=>`<button data-action="fork" data-id="${e(d.id)}" data-method="${key}">${name}<span>${prompts[key]}</span></button>`).join('')+'</div>','Fork from the concern');else if(a==='fork'){k.close();fork(k,d.id,d.method);}else if(['review','remove-design','remove-concern'].includes(a)){k.close();k.act({type:a,id:d.id});}else if(a==='select')k.act({type:a,id:d.id});}});
